//! Proves the overwrite prompt against a read-only runtime snapshot. Stops
//! before the original confirmation script; never opens or writes a save.
use gba_core::{Machine,ffta_battle_mouse as mouse};
fn main(){let rom=std::fs::read(std::env::args().nth(1).unwrap()).unwrap();for answer in [0u8,1]{let mut m=Machine::new(rom.clone());for(n,d)in[("ewram",&mut m.bus.ewram),("iwram",&mut m.bus.iwram),("vram",&mut m.bus.vram),("io",&mut m.bus.io),("oam",&mut m.bus.oam),("palette",&mut m.bus.palette)]{d.copy_from_slice(&std::fs::read(format!("target/save-overwrite3-6600-{n}.bin")).unwrap());}m.bus.ffta_movement.enabled=true;m.bus.ffta_movement.europe_profile=true;m.bus.ffta_dialogue.separate=true;assert!(m.bus.ffta_battle_mouse.enable_replay());gba_core::mem::set_extra(22);for y in 0..160{gba_core::ppu::render_scanline(&mut m.bus,y);}let c=mouse::DialogueChoice::read(&m.bus).unwrap();println!("SAVE_NOTICE bounds={:?} UI={:?}",c.bounds,gba_core::ffta_ui::Scene::capture(&m.bus.ffta_dialogue));let b=c.bounds[answer as usize];assert_eq!(c.hit((b[0]+1)as f32,(b[1]+1)as f32),Some(answer));assert_eq!(c.hit(150.,130.),None);assert!(c.select(&mut m.bus,answer,true));m.bus.iwram[..8].fill(0);m.bus.keys=0x3ff;m.cpu.cpsr=0xbf;m.cpu.regs[13]=0x03007b00;m.cpu.regs[14]=0x08000001;m.cpu.regs[15]=0x0801194c;m.cpu.branch=None;let mut reached=false;for _ in 0..100000{m.step();if m.cpu.regs[15]==0x08011b7e{reached=true;break;}}assert!(reached);assert_eq!(&m.bus.iwram[..8],&[0;8]);assert_eq!(m.bus.keys,0x3ff);println!("SAVE_NOTICE answer={answer} reached_original_branch=true global_keys_unchanged=true stopped_before_save=true");}}
